(959,1723,$mw$9D52C1935F033C454DA2DD6357DD018871574CDD862298F43060804A9F456061$mw$,$mw$6c2afd674e71eceb013c663fdb1971bc$mw$,$mw$$mw$,$mw${"Id":1723,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"احسب $\\log_{1/2}8$ وفسّر سبب إشارة النتيجة.","TitleEn":"Evaluate $\\log_{1/2}8$ and explain the sign of the result.","QuestionTextAr":"احسب $\\log_{1/2}8$ وفسّر سبب إشارة النتيجة.","QuestionTextEn":"Evaluate $\\log_{1/2}8$ and explain the sign of the result.","DetailedSolutionAr":"القانون المستخدم: $\\log_b y=x$ إذا وفقط إذا $b^x=y$، ويُسمح بأساس $0<b<1$ رغم أن الدالة تكون متناقصة. نحل $(1/2)^x=8=2^3$. لأن $(1/2)^x=2^{-x}$ فإن $-x=3$، أي $x=-3$. التحقق: $(1/2)^{-3}=8$.","DetailedSolutionEn":"Rule used: log_b(y)=x iff b^x=y, including valid bases 0<b<1. Solve (1/2)^x=8=2³. Since (1/2)^x=2^(−x), equate exponents to obtain −x=3 and x=−3. Check: (1/2)^(−3)=8; the logarithm is negative because the base is below 1.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6881,"Order":1,"LatexCode":"3","IsCorrect":false},{"Id":6882,"Order":2,"LatexCode":"-3","IsCorrect":true},{"Id":6883,"Order":3,"LatexCode":"-2","IsCorrect":false},{"Id":6884,"Order":4,"LatexCode":"4","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حوّل اللوغاريتم إلى معادلة أسية.","En":"Rewrite the logarithm as an exponential equation."},{"Ar":"استعمل قاعدة الأس السالب للمقلوب.","En":"Use the reciprocal rule for negative exponents."}],"Title":{"Ar":"احسب $\\log_{1/2}8$ وفسّر سبب إشارة النتيجة.","En":"Evaluate $\\log_{1/2}8$ and explain the sign of the result."},"Points":10,"Options":[{"Reason":{"Ar":"القوة الموجبة 3 تعطي 1/8 لا 8.","En":"Positive power 3 gives 1/8, not 8."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"3"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"-3"},{"Reason":{"Ar":"القوة −2 تعطي 4 لا 8.","En":"Power −2 gives 4, not 8."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"-2"},{"Reason":{"Ar":"القوة 4 تعطي 1/16.","En":"Power 4 gives 1/16."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"4"}],"StageId":3,"Question":{"Ar":"احسب $\\log_{1/2}8$ وفسّر سبب إشارة النتيجة.","En":"Evaluate $\\log_{1/2}8$ and explain the sign of the result."},"Solution":{"Idea":{"Ar":"عندما يكون الأساس بين صفر وواحد يكون اللوغاريتم سالباً للمدخل الأكبر من واحد.","En":"For a base between zero and one, the logarithm of an argument greater than one is negative."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$(1/2)^c=8$","En":"$(1/2)^c=8$"},{"Ar":"$2^{-c}=2^3\\Rightarrow -c=3$","En":"$2^{-c}=2^3\\Rightarrow -c=3$"},{"Ar":"إذن الأس سالب؛ لأن رفع أساس بين 0 و1 إلى قوة موجبة يعطي عدداً أصغر من 1، بينما المدخل 8 أكبر من 1.","En":"The exponent is negative: positive powers of a base between 0 and 1 are below 1, whereas the argument 8 is above 1."}],"Result":{"Ar":"$-3$","En":"$-3$"},"CommonError":{"Ar":"لا تتجاهل أن الأساس نصف لا اثنان.","En":"Do not ignore that the base is one half, not two."},"FormulaLatex":"\\log_ba=c\\iff b^c=a","Substitution":{"Ar":"$(1/2)^{-3}=2^3=8\\Rightarrow\\log_{1/2}8=-3$","En":"$(1/2)^{-3}=2^3=8\\Rightarrow\\log_{1/2}8=-3$"},"Verification":{"Ar":"$(1/2)^{-3}=8$","En":"$(1/2)^{-3}=8$"}},"TrackIds":[11],"CategoryId":86,"PrimarySkillId":313,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حوّل اللوغاريتم إلى معادلة أسية.","En":"Rewrite the logarithm as an exponential equation."},{"Ar":"استعمل قاعدة الأس السالب للمقلوب.","En":"Use the reciprocal rule for negative exponents."}],"Solution":{"Idea":{"Ar":"عندما يكون الأساس بين صفر وواحد يكون اللوغاريتم سالباً للمدخل الأكبر من واحد.","En":"For a base between zero and one, the logarithm of an argument greater than one is negative."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"$(1/2)^c=8$","En":"$(1/2)^c=8$"},{"Ar":"$2^{-c}=2^3\\Rightarrow -c=3$","En":"$2^{-c}=2^3\\Rightarrow -c=3$"},{"Ar":"إذن الأس سالب؛ لأن رفع أساس بين 0 و1 إلى قوة موجبة يعطي عدداً أصغر من 1، بينما المدخل 8 أكبر من 1.","En":"The exponent is negative: positive powers of a base between 0 and 1 are below 1, whereas the argument 8 is above 1."}],"Result":{"Ar":"$-3$","En":"$-3$"},"CommonError":{"Ar":"لا تتجاهل أن الأساس نصف لا اثنان.","En":"Do not ignore that the base is one half, not two."},"FormulaLatex":"\\log_ba=c\\iff b^c=a","Substitution":{"Ar":"$(1/2)^{-3}=2^3=8\\Rightarrow\\log_{1/2}8=-3$","En":"$(1/2)^{-3}=2^3=8\\Rightarrow\\log_{1/2}8=-3$"},"Verification":{"Ar":"$(1/2)^{-3}=8$","En":"$(1/2)^{-3}=8$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"القوة الموجبة 3 تعطي 1/8 لا 8.","En":"Positive power 3 gives 1/8, not 8."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"القوة −2 تعطي 4 لا 8.","En":"Power −2 gives 4, not 8."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"القوة 4 تعطي 1/16.","En":"Power 4 gives 1/16."},"Order":4}]}$mw$,$mw$عندما يكون الأساس بين صفر وواحد يكون اللوغاريتم سالباً للمدخل الأكبر من واحد.

$\log_ba=c\iff b^c=a$

1. $(1/2)^c=8$

2. $2^{-c}=2^3\Rightarrow -c=3$

3. إذن الأس سالب؛ لأن رفع أساس بين 0 و1 إلى قوة موجبة يعطي عدداً أصغر من 1، بينما المدخل 8 أكبر من 1.

$(1/2)^{-3}=2^3=8\Rightarrow\log_{1/2}8=-3$

$-3$ بلا وحدة قياس

$(1/2)^{-3}=8$

لا تتجاهل أن الأساس نصف لا اثنان.$mw$,$mw$For a base between zero and one, the logarithm of an argument greater than one is negative.

$\log_ba=c\iff b^c=a$

1. $(1/2)^c=8$

2. $2^{-c}=2^3\Rightarrow -c=3$

3. The exponent is negative: positive powers of a base between 0 and 1 are below 1, whereas the argument 8 is above 1.

$(1/2)^{-3}=2^3=8\Rightarrow\log_{1/2}8=-3$

$-3$ Dimensionless

$(1/2)^{-3}=8$

Do not ignore that the base is one half, not two.$mw$),
(960,1724,$mw$DFDBE16D591616DB365C0A35C8548CF8515D185B9AA81A3FF6CBED0F209257CE$mw$,$mw$6865381c8c82cc0a1e470363c7a28962$mw$,$mw$$mw$,$mw${"Id":1724,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"يُعرّف مستوى شدة الصوت بالديسيبل بـ $L=10\\log_{10}(I/I_0)$. إذا كانت الشدة $I=1000I_0$، فما المستوى ","TitleEn":"Sound intensity level is $L=10\\log_{10}(I/I_0)$ decibels. If $I=1000I_0$, what is $L$?","QuestionTextAr":"يُعرّف مستوى شدة الصوت بالديسيبل بـ $L=10\\log_{10}(I/I_0)$. إذا كانت الشدة $I=1000I_0$، فما المستوى $L$ بالديسيبل؟","QuestionTextEn":"Sound intensity level is $L=10\\log_{10}(I/I_0)$ decibels. If $I=1000I_0$, what is $L$?","DetailedSolutionAr":"القانون المستخدم: المقياس اللوغاريتمي لمستوى الصوت هو $L=10\\log_{10}(I/I_0)$ حيث نسبة الشدتين موجبة. نعوّض $I/I_0=1000=10^3$. إذن $\\log_{10}(1000)=3$، ومنه $L=10\\times3=30$ ديسيبل. الضرب بعشرة خارج اللوغاريتم جزء من القانون.","DetailedSolutionEn":"Rule used: Sound level in decibels is L=10 log_10(I/I₀), where I/I₀ is a positive intensity ratio. Here I/I₀=1000=10³, so log_10(1000)=3. Multiply by 10: L=10×3=30 dB; do not confuse the logarithm with the final scaled level.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6885,"Order":1,"LatexCode":"3","IsCorrect":false},{"Id":6886,"Order":2,"LatexCode":"30","IsCorrect":true},{"Id":6887,"Order":3,"LatexCode":"10","IsCorrect":false},{"Id":6888,"Order":4,"LatexCode":"300","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب نسبة الشدة إلى المرجع.","En":"Find the intensity-to-reference ratio."},{"Ar":"عوّض النسبة في النموذج واحسب اللوغاريتم ثم المعامل.","En":"Substitute the ratio, evaluate its logarithm, then apply the multiplier."}],"Title":{"Ar":"يُعرّف مستوى شدة الصوت بالديسيبل بـ $L=10\\log_{10}(I/I_0)$. إذا كانت الشدة $I=1000I_0$، فما المستوى ","En":"Sound intensity level is $L=10\\log_{10}(I/I_0)$ decibels. If $I=1000I_0$, what is $L$?"},"Points":10,"Options":[{"Reason":{"Ar":"3 قيمة اللوغاريتم قبل ضربها في 10.","En":"3 is the logarithm before multiplying by 10."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"3"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"30"},{"Reason":{"Ar":"10 هو المعامل وحده وليس نتيجة النموذج.","En":"10 is only the multiplier, not the model result."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"10"},{"Reason":{"Ar":"300 لا ينتج من ضرب 10 في 3.","En":"300 is not the product of 10 and 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"300"}],"StageId":3,"Question":{"Ar":"يُعرّف مستوى شدة الصوت بالديسيبل بـ $L=10\\log_{10}(I/I_0)$. إذا كانت الشدة $I=1000I_0$، فما المستوى $L$ بالديسيبل؟","En":"Sound intensity level is $L=10\\log_{10}(I/I_0)$ decibels. If $I=1000I_0$, what is $L$?"},"Solution":{"Idea":{"Ar":"النموذج اللوغاريتمي يقيس نسبة الشدة إلى الشدة المرجعية بالديسيبل.","En":"The logarithmic model expresses intensity relative to a reference in decibels."},"Unit":{"Ar":"ديسيبل","En":"dB"},"Steps":[{"Ar":"نسبة الشدة إلى مرجعها موجبة وتساوي 1000.","En":"The positive intensity-to-reference ratio is 1000."},{"Ar":"$I/I_0=1000=10^3$","En":"$I/I_0=1000=10^3$"},{"Ar":"$L=10\\log_{10}(10^3)=10\\cdot3=30$","En":"$L=10\\log_{10}(10^3)=10\\cdot3=30$"}],"Result":{"Ar":"$30$","En":"$30$"},"CommonError":{"Ar":"لا تنس المعامل 10 خارج اللوغاريتم.","En":"Do not forget the factor 10 outside the logarithm."},"FormulaLatex":"L=10\\log_{10}(I/I_0)","Substitution":{"Ar":"$I/I_0=1000=10^3,\\quad L=10(3)=30$","En":"$I/I_0=1000=10^3,\\quad L=10(3)=30$"},"Verification":{"Ar":"$10^{30/10}=1000$","En":"$10^{30/10}=1000$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":314,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب نسبة الشدة إلى المرجع.","En":"Find the intensity-to-reference ratio."},{"Ar":"عوّض النسبة في النموذج واحسب اللوغاريتم ثم المعامل.","En":"Substitute the ratio, evaluate its logarithm, then apply the multiplier."}],"Solution":{"Idea":{"Ar":"النموذج اللوغاريتمي يقيس نسبة الشدة إلى الشدة المرجعية بالديسيبل.","En":"The logarithmic model expresses intensity relative to a reference in decibels."},"Unit":{"Ar":"ديسيبل","En":"dB"},"Steps":[{"Ar":"نسبة الشدة إلى مرجعها موجبة وتساوي 1000.","En":"The positive intensity-to-reference ratio is 1000."},{"Ar":"$I/I_0=1000=10^3$","En":"$I/I_0=1000=10^3$"},{"Ar":"$L=10\\log_{10}(10^3)=10\\cdot3=30$","En":"$L=10\\log_{10}(10^3)=10\\cdot3=30$"}],"Result":{"Ar":"$30$","En":"$30$"},"CommonError":{"Ar":"لا تنس المعامل 10 خارج اللوغاريتم.","En":"Do not forget the factor 10 outside the logarithm."},"FormulaLatex":"L=10\\log_{10}(I/I_0)","Substitution":{"Ar":"$I/I_0=1000=10^3,\\quad L=10(3)=30$","En":"$I/I_0=1000=10^3,\\quad L=10(3)=30$"},"Verification":{"Ar":"$10^{30/10}=1000$","En":"$10^{30/10}=1000$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"3 قيمة اللوغاريتم قبل ضربها في 10.","En":"3 is the logarithm before multiplying by 10."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"10 هو المعامل وحده وليس نتيجة النموذج.","En":"10 is only the multiplier, not the model result."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"300 لا ينتج من ضرب 10 في 3.","En":"300 is not the product of 10 and 3."},"Order":4}]}$mw$,$mw$النموذج اللوغاريتمي يقيس نسبة الشدة إلى الشدة المرجعية بالديسيبل.

$L=10\log_{10}(I/I_0)$

1. نسبة الشدة إلى مرجعها موجبة وتساوي 1000.

2. $I/I_0=1000=10^3$

3. $L=10\log_{10}(10^3)=10\cdot3=30$

$I/I_0=1000=10^3,\quad L=10(3)=30$

$30$ ديسيبل

$10^{30/10}=1000$

لا تنس المعامل 10 خارج اللوغاريتم.$mw$,$mw$The logarithmic model expresses intensity relative to a reference in decibels.

$L=10\log_{10}(I/I_0)$

1. The positive intensity-to-reference ratio is 1000.

2. $I/I_0=1000=10^3$

3. $L=10\log_{10}(10^3)=10\cdot3=30$

$I/I_0=1000=10^3,\quad L=10(3)=30$

$30$ dB

$10^{30/10}=1000$

Do not forget the factor 10 outside the logarithm.$mw$),
(961,1725,$mw$C9984610046E66C58A7299357D16C23DC04C8663AEBFFDDB7E2EF4C1A780B5FC$mw$,$mw$005b354b72b01ed5db55c1a650e3dfde$mw$,$mw$$mw$,$mw${"Id":1725,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"يُحسب الأس الهيدروجيني بالعلاقة $pH=-\\log_{10}[H^+]$ عندما يُعبّر التركيز عن تركيز مولاري. إذا كان $[H^+]=10^{-4}$","TitleEn":"The pH model is $pH=-\\log_{10}[H^+]$ for molar hydrogen-ion concentration. If $[H^+]=10^{-4}$, find ","QuestionTextAr":"يُحسب الأس الهيدروجيني بالعلاقة $pH=-\\log_{10}[H^+]$ عندما يُعبّر التركيز عن تركيز مولاري. إذا كان $[H^+]=10^{-4}$، فما قيمة $pH$؟","QuestionTextEn":"The pH model is $pH=-\\log_{10}[H^+]$ for molar hydrogen-ion concentration. If $[H^+]=10^{-4}$, find pH.","DetailedSolutionAr":"القانون المستخدم: $pH=-\\log_{10}[H^+]$ عند التعبير عن تركيز الأيونات بالمول/لتر. بالتعويض $[H^+]=10^{-4}$، نحصل على $\\log_{10}(10^{-4})=-4$ لأن لوغاريتم قوة الأساس يعيد الأس. ثم $pH=-(-4)=4$. الإشارة السالبة خارج اللوغاريتم تغيّر النتيجة.","DetailedSolutionEn":"Rule used: In the standard molar-concentration model, pH = −log_10[H⁺]. With [H⁺]=10^(−4), the logarithm of a base-10 power equals its exponent: log_10(10^(−4))=−4. Therefore pH=−(−4)=4.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6889,"Order":1,"LatexCode":"-4","IsCorrect":false},{"Id":6890,"Order":2,"LatexCode":"4","IsCorrect":true},{"Id":6891,"Order":3,"LatexCode":"0.0001","IsCorrect":false},{"Id":6892,"Order":4,"LatexCode":"10","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"لاحظ الإشارة خارج اللوغاريتم.","En":"Notice the minus sign outside the logarithm."},{"Ar":"استخرج أس قوة العشرة ثم طبّق الإشارة الخارجية.","En":"Read the exponent of ten, then apply the outer sign."}],"Title":{"Ar":"يُحسب الأس الهيدروجيني بالعلاقة $pH=-\\log_{10}[H^+]$ عندما يُعبّر التركيز عن تركيز مولاري. إذا كان $[H^+]=10^{-4}$","En":"The pH model is $pH=-\\log_{10}[H^+]$ for molar hydrogen-ion concentration. If $[H^+]=10^{-4}$, find "},"Points":10,"Options":[{"Reason":{"Ar":"−4 يهمل الإشارة السالبة خارج اللوغاريتم.","En":"−4 omits the minus sign outside the logarithm."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"-4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"4"},{"Reason":{"Ar":"0.0001 هو التركيز المعطى وليس قيمة الأس الهيدروجيني.","En":"0.0001 is the concentration, not pH."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"0.0001"},{"Reason":{"Ar":"10 هو أساس اللوغاريتم وليس الناتج.","En":"10 is the logarithm base, not the result."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"10"}],"StageId":3,"Question":{"Ar":"يُحسب الأس الهيدروجيني بالعلاقة $pH=-\\log_{10}[H^+]$ عندما يُعبّر التركيز عن تركيز مولاري. إذا كان $[H^+]=10^{-4}$، فما قيمة $pH$؟","En":"The pH model is $pH=-\\log_{10}[H^+]$ for molar hydrogen-ion concentration. If $[H^+]=10^{-4}$, find pH."},"Solution":{"Idea":{"Ar":"وفق النموذج المعطى، لوغاريتم قوة العشرة هو أسها وتُعكس إشارته.","En":"In the stated model, the logarithm of a power of ten is its exponent, and the leading minus reverses its sign."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"التركيز المعطى موجب، ولذلك اللوغاريتم معرف في النموذج.","En":"The supplied concentration is positive, so the logarithm in the model is defined."},{"Ar":"$\\log_{10}(10^{-4})=-4$","En":"$\\log_{10}(10^{-4})=-4$"},{"Ar":"$pH=-(-4)=4$","En":"$pH=-(-4)=4$"}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تنس السالب خارج اللوغاريتم.","En":"Do not omit the outer negative sign."},"FormulaLatex":"pH=-\\log_{10}[H^+]","Substitution":{"Ar":"$pH=-\\log_{10}(10^{-4})=-(-4)=4$","En":"$pH=-\\log_{10}(10^{-4})=-(-4)=4$"},"Verification":{"Ar":"$10^{-4}=10^{-pH}$","En":"$10^{-4}=10^{-pH}$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":314,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"لاحظ الإشارة خارج اللوغاريتم.","En":"Notice the minus sign outside the logarithm."},{"Ar":"استخرج أس قوة العشرة ثم طبّق الإشارة الخارجية.","En":"Read the exponent of ten, then apply the outer sign."}],"Solution":{"Idea":{"Ar":"وفق النموذج المعطى، لوغاريتم قوة العشرة هو أسها وتُعكس إشارته.","En":"In the stated model, the logarithm of a power of ten is its exponent, and the leading minus reverses its sign."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"التركيز المعطى موجب، ولذلك اللوغاريتم معرف في النموذج.","En":"The supplied concentration is positive, so the logarithm in the model is defined."},{"Ar":"$\\log_{10}(10^{-4})=-4$","En":"$\\log_{10}(10^{-4})=-4$"},{"Ar":"$pH=-(-4)=4$","En":"$pH=-(-4)=4$"}],"Result":{"Ar":"$4$","En":"$4$"},"CommonError":{"Ar":"لا تنس السالب خارج اللوغاريتم.","En":"Do not omit the outer negative sign."},"FormulaLatex":"pH=-\\log_{10}[H^+]","Substitution":{"Ar":"$pH=-\\log_{10}(10^{-4})=-(-4)=4$","En":"$pH=-\\log_{10}(10^{-4})=-(-4)=4$"},"Verification":{"Ar":"$10^{-4}=10^{-pH}$","En":"$10^{-4}=10^{-pH}$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"−4 يهمل الإشارة السالبة خارج اللوغاريتم.","En":"−4 omits the minus sign outside the logarithm."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"0.0001 هو التركيز المعطى وليس قيمة الأس الهيدروجيني.","En":"0.0001 is the concentration, not pH."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"10 هو أساس اللوغاريتم وليس الناتج.","En":"10 is the logarithm base, not the result."},"Order":4}]}$mw$,$mw$وفق النموذج المعطى، لوغاريتم قوة العشرة هو أسها وتُعكس إشارته.

$pH=-\log_{10}[H^+]$

1. التركيز المعطى موجب، ولذلك اللوغاريتم معرف في النموذج.

2. $\log_{10}(10^{-4})=-4$

3. $pH=-(-4)=4$

$pH=-\log_{10}(10^{-4})=-(-4)=4$

$4$ بلا وحدة قياس

$10^{-4}=10^{-pH}$

لا تنس السالب خارج اللوغاريتم.$mw$,$mw$In the stated model, the logarithm of a power of ten is its exponent, and the leading minus reverses its sign.

$pH=-\log_{10}[H^+]$

1. The supplied concentration is positive, so the logarithm in the model is defined.

2. $\log_{10}(10^{-4})=-4$

3. $pH=-(-4)=4$

$pH=-\log_{10}(10^{-4})=-(-4)=4$

$4$ Dimensionless

$10^{-4}=10^{-pH}$

Do not omit the outer negative sign.$mw$),
(962,1726,$mw$255F11D07A6D096F1EC850E90A93E4506B1F2642AC33EE71866FC97188F28F92$mw$,$mw$2d71fad78341c75538cc7e6271e65595$mw$,$mw$$mw$,$mw${"Id":1726,"StageId":3,"CategoryId":86,"Points":10,"TitleAr":"إذا علمت أن $\\log_2 3=a$، فاكتب $\\log_2 24$ بدلالة $a$.","TitleEn":"Given $\\log_2 3=a$, express $\\log_2 24$ in terms of $a$.","QuestionTextAr":"إذا علمت أن $\\log_2 3=a$، فاكتب $\\log_2 24$ بدلالة $a$.","QuestionTextEn":"Given $\\log_2 3=a$, express $\\log_2 24$ in terms of $a$.","DetailedSolutionAr":"القانون المستخدم: $\\log_b(MN)=\\log_b M+\\log_b N$ عندما يكون المدخلان موجبين. نحلّل $24=8\\times3=2^3\\times3$. إذن $\\log_2 24=\\log_2 8+\\log_2 3=3+a$. لا نضرب اللوغاريتمين معاً لأن قانون الضرب داخل المدخل يتحول إلى جمع في الخارج.","DetailedSolutionEn":"Rule used: For positive inputs, log_b(MN)=log_b(M)+log_b(N). Factor 24=8×3=2³×3. Thus log_2(24)=log_2(8)+log_2(3)=3+a. Multiplication inside a logarithm turns into addition of the logarithms, not multiplication of their values.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6893,"Order":1,"LatexCode":"3a","IsCorrect":false},{"Id":6894,"Order":2,"LatexCode":"a+3","IsCorrect":true},{"Id":6895,"Order":3,"LatexCode":"a+8","IsCorrect":false},{"Id":6896,"Order":4,"LatexCode":"a-3","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حلل 24 إلى حاصل ضرب 3 وقوة للعدد 2.","En":"Factor 24 into 3 times a power of 2."},{"Ar":"طبّق خاصية الجداء واستبدل اللوغاريتم المعطى بالرمز a.","En":"Apply the product rule and replace the given logarithm with a."}],"Title":{"Ar":"إذا علمت أن $\\log_2 3=a$، فاكتب $\\log_2 24$ بدلالة $a$.","En":"Given $\\log_2 3=a$, express $\\log_2 24$ in terms of $a$."},"Points":10,"Options":[{"Reason":{"Ar":"3a يضرب اللوغاريتمين بدلاً من جمعهما.","En":"3a multiplies the logarithm values rather than adding them."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"3a"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"a+3"},{"Reason":{"Ar":"a+8 يجمع العدد 8 نفسه بدلاً من لوغاريتمه 3.","En":"a+8 adds 8 itself instead of its logarithm 3."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"a+8"},{"Reason":{"Ar":"a−3 يستعمل قاعدة القسمة بدلاً من الجداء.","En":"a−3 uses the quotient rule instead of the product rule."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"a-3"}],"StageId":3,"Question":{"Ar":"إذا علمت أن $\\log_2 3=a$، فاكتب $\\log_2 24$ بدلالة $a$.","En":"Given $\\log_2 3=a$, express $\\log_2 24$ in terms of $a$."},"Solution":{"Idea":{"Ar":"نحلل المدخل إلى عامل معلوم اللوغاريتم وعامل يمكن حسابه.","En":"Factor the argument into one factor with a known logarithm and another that can be evaluated."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نحلل 24 إلى عامل معلوم اللوغاريتم وقوة للعدد 2، وكلاهما موجب.","En":"Factor 24 into a known logarithm argument and a power of 2; both are positive."},{"Ar":"$24=3\\cdot8=3\\cdot2^3$","En":"$24=3\\cdot8=3\\cdot2^3$"},{"Ar":"$\\log_2 24=\\log_2 3+\\log_2(2^3)=a+3$","En":"$\\log_2 24=\\log_2 3+\\log_2(2^3)=a+3$"}],"Result":{"Ar":"$a+3$","En":"$a+3$"},"CommonError":{"Ar":"لا تضرب a في أس العامل الآخر.","En":"Do not multiply a by the exponent of the other factor."},"FormulaLatex":"\\log_b(uv)=\\log_bu+\\log_bv","Substitution":{"Ar":"$24=3\\times8,\\quad\\log_2 24=\\log_2 3+\\log_2 8=a+3$","En":"$24=3\\times8,\\quad\\log_2 24=\\log_2 3+\\log_2 8=a+3$"},"Verification":{"Ar":"$2^{a+3}=3\\times8=24$","En":"$2^{a+3}=3\\times8=24$"}},"TrackIds":[12],"CategoryId":86,"PrimarySkillId":315,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حلل 24 إلى حاصل ضرب 3 وقوة للعدد 2.","En":"Factor 24 into 3 times a power of 2."},{"Ar":"طبّق خاصية الجداء واستبدل اللوغاريتم المعطى بالرمز a.","En":"Apply the product rule and replace the given logarithm with a."}],"Solution":{"Idea":{"Ar":"نحلل المدخل إلى عامل معلوم اللوغاريتم وعامل يمكن حسابه.","En":"Factor the argument into one factor with a known logarithm and another that can be evaluated."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نحلل 24 إلى عامل معلوم اللوغاريتم وقوة للعدد 2، وكلاهما موجب.","En":"Factor 24 into a known logarithm argument and a power of 2; both are positive."},{"Ar":"$24=3\\cdot8=3\\cdot2^3$","En":"$24=3\\cdot8=3\\cdot2^3$"},{"Ar":"$\\log_2 24=\\log_2 3+\\log_2(2^3)=a+3$","En":"$\\log_2 24=\\log_2 3+\\log_2(2^3)=a+3$"}],"Result":{"Ar":"$a+3$","En":"$a+3$"},"CommonError":{"Ar":"لا تضرب a في أس العامل الآخر.","En":"Do not multiply a by the exponent of the other factor."},"FormulaLatex":"\\log_b(uv)=\\log_bu+\\log_bv","Substitution":{"Ar":"$24=3\\times8,\\quad\\log_2 24=\\log_2 3+\\log_2 8=a+3$","En":"$24=3\\times8,\\quad\\log_2 24=\\log_2 3+\\log_2 8=a+3$"},"Verification":{"Ar":"$2^{a+3}=3\\times8=24$","En":"$2^{a+3}=3\\times8=24$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"3a يضرب اللوغاريتمين بدلاً من جمعهما.","En":"3a multiplies the logarithm values rather than adding them."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"a+8 يجمع العدد 8 نفسه بدلاً من لوغاريتمه 3.","En":"a+8 adds 8 itself instead of its logarithm 3."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"a−3 يستعمل قاعدة القسمة بدلاً من الجداء.","En":"a−3 uses the quotient rule instead of the product rule."},"Order":4}]}$mw$,$mw$نحلل المدخل إلى عامل معلوم اللوغاريتم وعامل يمكن حسابه.

$\log_b(uv)=\log_bu+\log_bv$

1. نحلل 24 إلى عامل معلوم اللوغاريتم وقوة للعدد 2، وكلاهما موجب.

2. $24=3\cdot8=3\cdot2^3$

3. $\log_2 24=\log_2 3+\log_2(2^3)=a+3$

$24=3\times8,\quad\log_2 24=\log_2 3+\log_2 8=a+3$

$a+3$ بلا وحدة قياس

$2^{a+3}=3\times8=24$

لا تضرب a في أس العامل الآخر.$mw$,$mw$Factor the argument into one factor with a known logarithm and another that can be evaluated.

$\log_b(uv)=\log_bu+\log_bv$

1. Factor 24 into a known logarithm argument and a power of 2; both are positive.

2. $24=3\cdot8=3\cdot2^3$

3. $\log_2 24=\log_2 3+\log_2(2^3)=a+3$

$24=3\times8,\quad\log_2 24=\log_2 3+\log_2 8=a+3$

$a+3$ Dimensionless

$2^{a+3}=3\times8=24$

Do not multiply a by the exponent of the other factor.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
